const lockMergedPredecessorHolds = `-- name: LockMergedPredecessorHolds :many
SELECT id, generation FROM recovery_custody_holds
WHERE run_id = $1 AND user_id = $2 AND repo_id = $3
    AND state = 'open' AND generation < $4
ORDER BY generation, id LIMIT 1001 FOR NO KEY UPDATE
`

type LockMergedPredecessorHoldsParams struct {
	RunID               uuid.UUID   `json:"run_id"`
	OwnerID             uuid.UUID   `json:"owner_id"`
	RepoID              pgtype.UUID `json:"repo_id"`
	CompletedGeneration int64       `json:"completed_generation"`
}

type LockMergedPredecessorHoldsRow struct {
	ID         uuid.UUID `json:"id"`
	Generation int64     `json:"generation"`
}

// Discard changes no referenced key. NO KEY UPDATE excludes other disposers while
// permitting an admitted upload's FK key-share check to finish before capture locking.
func (q *Queries) LockMergedPredecessorHolds(ctx context.Context, arg LockMergedPredecessorHoldsParams) ([]LockMergedPredecessorHoldsRow, error) {
	rows, err := q.db.Query(ctx, lockMergedPredecessorHolds,
		arg.RunID,
		arg.OwnerID,
		arg.RepoID,
		arg.CompletedGeneration,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockMergedPredecessorHoldsRow{}
	for rows.Next() {
		var i LockMergedPredecessorHoldsRow
		if err := rows.Scan(&i.ID, &i.Generation); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockMergedPredecessorNonReadyCaptures = `-- name: LockMergedPredecessorNonReadyCaptures :many
SELECT id FROM recovery_captures
WHERE hold_id = $1 AND state IN ('preparing', 'uploading', 'needs_action')
ORDER BY id LIMIT $2::int FOR UPDATE
`

type LockMergedPredecessorNonReadyCapturesParams struct {
	HoldID       uuid.UUID `json:"hold_id"`
	CaptureLimit int32     `json:"capture_limit"`
}

func (q *Queries) LockMergedPredecessorNonReadyCaptures(ctx context.Context, arg LockMergedPredecessorNonReadyCapturesParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockMergedPredecessorNonReadyCaptures, arg.HoldID, arg.CaptureLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockMergedPredecessorRun = `-- name: LockMergedPredecessorRun :one
SELECT id, user_id, repo_id, status, claim_generation, mr_iid
FROM runs WHERE id = $1 FOR UPDATE
`

type LockMergedPredecessorRunRow struct {
	ID              uuid.UUID   `json:"id"`
	UserID          uuid.UUID   `json:"user_id"`
	RepoID          pgtype.UUID `json:"repo_id"`
	Status          string      `json:"status"`
	ClaimGeneration int64       `json:"claim_generation"`
	MrIid           pgtype.Int8 `json:"mr_iid"`
}

func (q *Queries) LockMergedPredecessorRun(ctx context.Context, runID uuid.UUID) (LockMergedPredecessorRunRow, error) {
	row := q.db.QueryRow(ctx, lockMergedPredecessorRun, runID)
	var i LockMergedPredecessorRunRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.RepoID,
		&i.Status,
		&i.ClaimGeneration,
		&i.MrIid,
	)
	return i, err
}
